using Commerce;

namespace Commerce.Tests;

[TestClass]
public sealed class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // ─── AddItem ────────────────────────────────────────────

    [TestMethod]
    public void AddItem_SingleItem_IncreasesTotal()
    {
        _cart.AddItem("SKU-001", 9.99m, 1);

        Assert.AreEqual(9.99m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleQuantity_MultipliesPrice()
    {
        _cart.AddItem("SKU-001", 5.00m, 3);

        Assert.AreEqual(15.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_MultipleDifferentItems_SumsAll()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        _cart.AddItem("SKU-002", 20.00m, 2);

        Assert.AreEqual(50.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void AddItem_DuplicateSku_AddsBothEntries()
    {
        _cart.AddItem("SKU-001", 5.00m, 1);
        _cart.AddItem("SKU-001", 5.00m, 1);

        Assert.AreEqual(10.00m, _cart.GetTotal());
    }

    // ─── RemoveItem ─────────────────────────────────────────

    [TestMethod]
    public void RemoveItem_ExistingItem_ReturnsTrue()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);

        Assert.IsTrue(_cart.RemoveItem("SKU-001"));
    }

    [TestMethod]
    public void RemoveItem_ExistingItem_ReducesTotal()
    {
        _cart.AddItem("SKU-001", 10.00m, 1);
        _cart.AddItem("SKU-002", 20.00m, 1);

        _cart.RemoveItem("SKU-001");

        Assert.AreEqual(20.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistentItem_ReturnsFalse()
    {
        Assert.IsFalse(_cart.RemoveItem("NOPE"));
    }

    [TestMethod]
    public void RemoveItem_DuplicateSku_RemovesAllEntries()
    {
        _cart.AddItem("SKU-001", 5.00m, 1);
        _cart.AddItem("SKU-001", 7.00m, 2);

        _cart.RemoveItem("SKU-001");

        Assert.AreEqual(0m, _cart.GetTotal());
    }

    // ─── GetTotal ───────────────────────────────────────────

    [TestMethod]
    public void GetTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.GetTotal());
    }

    [TestMethod]
    [DataRow(1, 10.00, 10.00)]
    [DataRow(5, 3.50, 17.50)]
    [DataRow(0, 99.99, 0.00)]
    public void GetTotal_VariousQuantities_ReturnsCorrectAmount(
        int qty, double price, double expectedTotal)
    {
        _cart.AddItem("SKU-001", (decimal)price, qty);

        Assert.AreEqual((decimal)expectedTotal, _cart.GetTotal());
    }

    // ─── ApplyPromoCode ─────────────────────────────────────

    [TestMethod]
    public void ApplyPromoCode_ValidCode_ReturnsTrue()
    {
        Assert.IsTrue(_cart.ApplyPromoCode("SAVE10"));
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_ReturnsFalse()
    {
        Assert.IsFalse(_cart.ApplyPromoCode("BOGUS"));
    }

    [TestMethod]
    public void ApplyPromoCode_CaseInsensitive_ReturnsTrue()
    {
        Assert.IsTrue(_cart.ApplyPromoCode("save10"));
    }

    [TestMethod]
    [DataRow("SAVE10", 90.00)]
    [DataRow("SAVE20", 80.00)]
    [DataRow("HALF", 50.00)]
    public void ApplyPromoCode_DiscountsTotal(string code, double expectedTotal)
    {
        _cart.AddItem("SKU-001", 100.00m, 1);

        _cart.ApplyPromoCode(code);

        Assert.AreEqual((decimal)expectedTotal, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_InvalidCode_DoesNotAffectTotal()
    {
        _cart.AddItem("SKU-001", 100.00m, 1);

        _cart.ApplyPromoCode("INVALID");

        Assert.AreEqual(100.00m, _cart.GetTotal());
    }

    [TestMethod]
    public void ApplyPromoCode_OnEmptyCart_TotalRemainsZero()
    {
        _cart.ApplyPromoCode("SAVE20");

        Assert.AreEqual(0m, _cart.GetTotal());
    }
}

